head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil52000";
scwin.form = null;
scwin.searchType = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil52000.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb0", fn: function () { return "전체 " + String((dma_pageContext.get("totalCountIntValue") ?? "")) + "건 [" + String((dma_pageContext.get("currentPage") ?? "")) + "/" + String((dma_pageContext.get("totalPageCount") ?? "")) + "Page]"; } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        scwin.form = (document.prtDepoListForm || { elements: [] });

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil52000.onpageload' }); }
};

// [A] 초기 목록 미해결 — 진입 근거가 다른 액션을 가리킨다(prtdepolist vs prtdepo) — 어느 쪽인지 정할 근거가 없다

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_prtDepoList_oncellclick
 * @description grd_prtDepoList 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_prtDepoList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_prtDepoList');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_prtDepoList */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (columnId === "__rowAct") { if (r["lstApprovYn"] === '0' && r["listProcsStatCd"] === '') { await scwin.sendPrtDepoWithd(r["prtdepoNo"], "2"); return; } if ((r["lstApprovYn"] === '0' || r["lstApprovYn"] === '3') && r["listProcsStatCd"] === '35') { await scwin.sendPrtDepoWithd(r["prtdepoNo"], "3"); return; } if ((r["lstApprovYn"] === '0' || r["lstApprovYn"] === '7') &&  r["listProcsStatCd"] === '37') { await scwin.sendPrtDepoWithd(r["prtdepoNo"], "3"); return; } if (r["lstApprovYn"] === '7' &&  r["listProcsStatCd"] === '38') { await scwin.sendPrtDepoWithd(r["prtdepoNo"], "3"); return; } if (r["lstApprovYn"] === '3' && (r["listProcsStatCd"] === '33' || r["listProcsStatCd"] === '36' || r["listProcsStatCd"] === '37')) { await scwin.openAdjReqPop(r["prtdepoNo"], "150"); return; } return; } if (r["lstApprovYn"] === '0' && (r["listProcsStatCd"] === '' || r["listProcsStatCd"] === '35')) { await scwin.viewDetail(r["prtdepoNo"], r["lstApprovYn"], r["listProcsStatCd"]); return; }
        if (r["lstApprovYn"] === '3' && r["listProcsStatCd"] === '35') { await scwin.viewDetail(r["prtdepoNo"], r["lstApprovYn"], r["listProcsStatCd"]); return; }
        if ((r["lstApprovYn"] === '0' || r["lstApprovYn"] === '7') &&  r["listProcsStatCd"] === '37') { await scwin.viewDetail(r["prtdepoNo"], r["lstApprovYn"], r["listProcsStatCd"]); return; }
        if (r["lstApprovYn"] === '7' &&  r["listProcsStatCd"] === '38') { await scwin.viewDetail(r["prtdepoNo"], r["lstApprovYn"], r["listProcsStatCd"]); return; }
        await scwin.viewDetail(r["prtdepoNo"], r["lstApprovYn"], r["listProcsStatCd"]); return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_prtDepoList.oncellclick' });
    }
};

/**
 * @method
 * @name btn_newWrite_onclick
 * @description 「신규작성」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_newWrite_onclick = function(e){
    try {
        scwin.newWrite()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil52000.btn_newWrite_onclick' }); }
};

/**
 * @method
 * @name krxpage_pagenavigator_78_onclick
 * @description krxpage_pagenavigator_78 클릭 이벤트
 * @param {Number} index index
 * @returns {void}
 * @hidden N
 */
scwin.krxpage_pagenavigator_78_onclick = async function (index) {
    try {
        const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index;
        $c.util.getComponent('dma_viewDetailReq').set('pageIndex', pi);
        await scwin.fncSearch();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldfil52000.krxpage_pagenavigator_78_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_viewDetail
 * @description view Detail 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_viewDetail = async function () {
    const sbmOptions = {
        id: "tx_viewDetail",
        method: "post",
        action: "/listInvstg/prtDepo.do?method=loadDetail&bzCd=6",
        ref: "dma_viewDetailReq",
        target: "dlt_prtDepoList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_searchCorpListByBeginIndex
 * @description search Corp List By Begin Index 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_searchCorpListByBeginIndex = async function () {
    const sbmOptions = {
        id: "tx_searchCorpListByBeginIndex",
        method: "post",
        action: "/listInvstg/prtDepoList.do?method=getPrtDepoList",
        ref: "dma_searchCorpListByBeginIndexReq",
        target: "dlt_prtDepoList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_delete
 * @description delete 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_delete = async function () {
    const sbmOptions = {
        id: "tx_fn_delete",
        method: "post",
        action: "/listInvstg/prtDepoList.do",
        ref: "dma_deleteReq",
        target: "dlt_prtDepoList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_sendPrtDepoWithd
 * @description send Prt Depo Withd 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_sendPrtDepoWithd = async function () {
    const sbmOptions = {
        id: "tx_sendPrtDepoWithd",
        method: "post",
        action: "/listInvstg/prtDepoList.do",
        ref: "dma_sendPrtDepoWithdReq",
        target: "dlt_prtDepoList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name grd_prtDepoList_fillAct
 * @description grd prt Depo List fill Act 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_prtDepoList_fillAct = async function () {
    try {
        const dl = $c.util.getComponent('dlt_prtDepoList');
        if (!dl || !dl.getTotalRow) { return; }
        for (let i = 0; i < dl.getRowCount(); i++) {
            const r = dl.getRowJSON(i);
            let v = '-';
            if (r) { if (r["lstApprovYn"] === '0' && r["listProcsStatCd"] === '') { v = "제출"; } else if ((r["lstApprovYn"] === '0' || r["lstApprovYn"] === '3') && r["listProcsStatCd"] === '35') { v = "제출"; } else if ((r["lstApprovYn"] === '0' || r["lstApprovYn"] === '7') &&  r["listProcsStatCd"] === '37') { v = "제출"; } else if (r["lstApprovYn"] === '7' &&  r["listProcsStatCd"] === '38') { v = "제출"; } else if (r["lstApprovYn"] === '3' && (r["listProcsStatCd"] === '33' || r["listProcsStatCd"] === '36' || r["listProcsStatCd"] === '37')) { v = "수정요청"; } }
            dl.setCellData(i, "__rowAct", v);
        }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_prtDepoList.fillAct' });
    }
};

/**
 * @method
 * @name viewDetail
 * @description view Detail 처리
 * @param {*} prtDepoNo prtDepoNo
 * @param {String} approvYn approvYn
 * @param {String} procsStatCd procsStatCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.viewDetail = async function (prtDepoNo, approvYn, procsStatCd) {
    $c.util.getComponent('dma_viewDetailReq').set('prtDepoNo', prtDepoNo);
    if (approvYn === '0' || approvYn === '7') {
        if (procsStatCd === '38') {
            scwin.searchType = '5';
        } else {
            scwin.searchType = '2';
        }
    } else {
        if (approvYn === '2') {
            if (procsStatCd === '38') {
                scwin.searchType = '5';
            } else {
                scwin.searchType = '1';
            }
        } else {
            if (approvYn === '3') {
                if (procsStatCd === '34') {
                    scwin.searchType = '1';
                } else {
                    if (procsStatCd === '35') {
                        scwin.searchType = '3';
                    } else {
                        scwin.searchType = '1';
                    }
                }
            } else {
                if (approvYn === '8') {
                    scwin.searchType = '4';
                } else {
                    if (approvYn === '9') {
                        scwin.searchType = '5';
                    }
                }
            }
        }
    }
    $c.util.getComponent('dma_viewDetailReq').set('searchType', scwin.searchType);
    scwin.form.action = '/listInvstg/prtDepo.do?method=loadDetail&bzCd=6';
    $c.util.getComponent('dma_viewDetailReq').set('method', 'loadDetail');
    await scwin.tx_viewDetail();
};

/**
 * @method
 * @name newWrite
 * @description new Write 처리
 * @returns {void}
 * @hidden N
 */
scwin.newWrite = function () {
    $c.win.setPageFrameSrc($c.win.getFrame(), '/jldfil52100/jldfil52100.xml');
};

/**
 * @method
 * @name newDisplay
 * @description new Display 처리
 * @returns {void}
 * @hidden N
 */
scwin.newDisplay = function () {
    ($c.util.getComponent('select_new_write') && $c.util.getComponent('select_new_write').show ? $c.util.getComponent('select_new_write').show() : console.warn('[sdd] show 대상 미해결: ' + 'select_new_write'));
};

/**
 * @method
 * @name fncSearch
 * @description fnc Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fncSearch = async function () {
    const pageIndex = $c.util.getComponent('dma_viewDetailReq').get('pageIndex');
    $c.util.getComponent('dma_viewDetailReq').set('pageIndex', pageIndex);
    await scwin.searchCorpListByBeginIndex();
};

/**
 * @method
 * @name searchCorpListByBeginIndex
 * @description search Corp List By Begin Index 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchCorpListByBeginIndex = async function () {
    await scwin.tx_searchCorpListByBeginIndex();
};

/**
 * @method
 * @name deleteViewDetailReq
 * @description delete View Detail Req 처리
 * @param {*} prtDepoNo prtDepoNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.deleteViewDetailReq = async function (prtDepoNo) {
    $c.util.getComponent('dma_viewDetailReq').set('prtDepoNo', prtDepoNo);
    const rse = await $c.win.confirm("삭제 하시겠습니까? ");
    if (rse) {
        scwin.form.action = '/listInvstg/prtDepoList.do';
        $c.util.getComponent('dma_viewDetailReq').set('method', 'delPrtDepoWithd');
        const nr = await scwin.tx_fn_delete();
        if (nr && nr.responseJSON && nr.responseJSON.success === true) {
            $c.win.moveUrl("/jldfil52101/jldfil52101.xml", { "prtDepoNo": prtDepoNo, "method": 'delPrtDepoWithd' });
        }
    }
};

/**
 * @method
 * @name sendPrtDepoWithd
 * @description send Prt Depo Withd 처리
 * @param {*} prtDepoNo prtDepoNo
 * @param {*} updateType updateType
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.sendPrtDepoWithd = async function (prtDepoNo, updateType) {
    scwin.form = (document.prtDepoListForm || { elements: [] });
    const rse = await $c.win.confirm("제출 하시겠습니까? ");
    if (rse) {
        $c.util.getComponent('dma_viewDetailReq').set('prtDepoNo', prtDepoNo);
        $c.util.getComponent('dma_viewDetailReq').set('searchType', updateType);
        scwin.form.action = '/listInvstg/prtDepoList.do';
        $c.util.getComponent('dma_viewDetailReq').set('method', 'sendPrtDepoWithd');
        const nr = await scwin.tx_sendPrtDepoWithd();
        if (nr && nr.responseJSON && nr.responseJSON.success === true) {
            $c.win.moveUrl("/jldfil52101/jldfil52101.xml", { "prtDepoNo": prtDepoNo, "searchType": updateType, "method": 'sendPrtDepoWithd' });
        }
    }
};

/**
 * @method
 * @name openAdjReqPop
 * @description open Adj Req Pop 처리
 * @param {*} prtdepoNo prtdepoNo
 * @param {String} listInvstgBzTpCd listInvstgBzTpCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openAdjReqPop = async function (prtdepoNo, listInvstgBzTpCd) {
    const data = { bzProcsNo: prtdepoNo, listInvstgBzTpCd: listInvstgBzTpCd, listBzDtlTpCd: "23", callbackFn: "scwin.popupCallback" };
    const options = { id: "jldfil59411", popupName: "상장공시제출시스템 수정요청", width: 900, height: 380, frameModal: "top" };
    await $c.win.openPopup("/jldfil59411/jldfil59411.xml", options, data);
};
